/**
 *  What a verdict cost the player, which is a fact whatever the manager makes
 *  of the line that reported it.
 * 
 *  The axis that replaced a confidence word. How firmly a log code can be read
 *  is a claim about the manager's own table and belongs to the sentence that
 *  reads the code, not stamped over what happened to the game.
 * 
 *  Ordered by how much the game lost, worst last.
 */
export type Consequence = 
/**  The overlay served the game without one archive, and the rest applied. */
"archive-dropped" | 
/**  No mod reached the game. */
"overlay-off" | 
/**  The game stopped making progress and never reached play. */
"game-hung" | 
/**  The game did not survive. */
"game-stopped";

/**  A single file entry in a layer's content directory. */
export type ContentEntry = {
	/**  Path relative to the layer root, always POSIX-style (`/`). */
	relativePath: string,
	sizeBytes: number,
	kind: WorkshopFileKind,
	/**  The objects a `.bin` declares, and empty for any other file. */
	objects: ContentObject[],
	/**  What leaves the file out of a package, null for one that ships. */
	ignoredBy: IgnoreMatch | null,
};

/**  One object a layer's `.bin` declares. */
export type ContentObject = {
	/**  The object's path hash, as `0x` and eight hex digits. */
	objectHash: string,
	/**  The object's path, or its hash when no table names it. */
	path: string,
	/**  The class the object declares, or its hash when no table names it. */
	class: string,
	/**  The class hash, as `0x` and eight hex digits. */
	classHash: string,
};

/**  A project's content directory as a flat per-layer listing. */
export type ContentTree = {
	layers: LayerContent[],
};

/**  Arguments for turning a folder into a project. */
export type ConvertFolderArgs = {
	path: string,
	name: string,
	displayName: string,
	placement: ConvertPlacement,
};

/**  Where a converted folder's project lives. */
export type ConvertPlacement = 
/**  The folder itself becomes the project. */
"inPlace" | 
/**  A copy in the workshop folder becomes the project, and the folder is left alone. */
"copy";

/**  How many problems a run holds at each severity. */
export type Counts = {
	fatals: number,
	errors: number,
	warnings: number,
	infos: number,
};

/**  Arguments for creating a new project. */
export type CreateProjectArgs = {
	name: string,
	displayName: string,
	description: string,
	authors: string[],
};

/**  Metadata for a discovered cslol-manager mod, shown in the UI selection step. */
export type CslolModInfo = {
	folderName: string,
	name: string,
	author: string,
	version: string,
	description: string,
};

/**  One layer's declarations manifest, read for an outline. */
export type DeclarationsLayer = {
	layer: string,
	/**  The manifest's path inside the layer, `None` for a layer with none. */
	file: string | null,
	/**  The manifest's text with `\r\n` read as `\n`, which every span indexes. */
	text: string | null,
	/**  Why the declarations do not load. `modules` is empty beside one. */
	error: DeclarationsLoadError | null,
	/**  The modules in execution order. */
	modules: DeclaredModule[],
};

/**  Why a layer's declarations do not load, and where. */
export type DeclarationsLoadError = {
	message: string,
	/**  The file the error is in, as the loader names it: the manifest's name or a source path. */
	document: string | null,
	/**  Where in the manifest, `None` for an error in another file or at no place. */
	span: LineSpan | null,
};

/**  One diagnostic of the last apply, on the row it names. */
export type DeclaredDiagnostic = {
	/**
	 *  The object's path hash, `0x` and eight hex digits. Empty where the diagnostic names no
	 *  object of the chunk.
	 */
	entry: string,
	/**
	 *  The row's hash path. Empty where the key reaches no row, which lists the
	 *  diagnostic under its object.
	 */
	path: string,
	/**  The layer whose declaration raised it. */
	layer: string,
	/**  The signed key, the link path or the override path the diagnostic is about. */
	key: string,
	kind: DeclaredDiagnosticKind,
	/**  Why a property edit was skipped. Absent for every other kind. */
	reason: SkipReason | null,
	/**  Why an object's creation or removal was skipped. Absent for every other kind. */
	object: ObjectSkip | null,
	/**  What a lower layer said, where it said something the codes do not carry. */
	detail: string | null,
};

/**  The category of a [`DeclaredDiagnostic`], as `ltk_game_data` names it. */
export type DeclaredDiagnosticKind = "overrideUnreadable" | "overrideInvalid" | "overrideRecordSkipped" | "linkRemovalUnmatched" | "propertyEditSkipped" | 
/**  A property typed from the game's copy, the schema saying nothing. Information. */
"schemaFallback" | "referenceUnreadable" | 
/**  An object's creation or removal that does not apply. */
"objectSkipped" | "unknown";

/**  One entry a module declares properties of, or one object it creates or removes. */
export type DeclaredEntry = {
	/**  The entry name as spelled. */
	name: string,
	/**  The path the hashtables give a name spelled as a hash, `None` for any other name. */
	knownName: string | null,
	/**  The object's path hash, `0x` and eight hex digits. */
	hash: string,
	/**  The edit of a `target` module the entry sits in, zero-based. */
	edit: number,
	/**  What an `objects` binding does to the object, `None` for an entry body. */
	object: DeclaredObjectEdit | null,
	/**  The line naming the entry. */
	span: LineSpan | null,
	keys: DeclaredKey[],
	/**  The dependencies an `entries` module adds to and removes from each declaring chunk. */
	links: DeclaredLinks,
};

/**  One signed property key of an entry body. */
export type DeclaredKey = {
	/**  The key as the build reads it, sign included. */
	key: string,
	sign: DeclaredSign,
	/**  The property path, without the sign. */
	path: string,
	/**  The value as YAML text: the manifest's own spelling where it is in the manifest. */
	value: string,
	/**
	 *  The wire path of the row the key reaches, cut before the first map key, which only
	 *  the bin itself can spell.
	 */
	row: string,
	/**  From the key to the end of its value. */
	span: LineSpan | null,
};

/**  What the schema declares for a field, beside whether the file's kind is that. */
export type DeclaredKind = {
	shape: KindShape,
	/**
	 *  The file's kind is not the declared one, as the Problems rule for a property
	 *  type reads the two.
	 */
	mismatch: boolean,
};

/**  What a declaration of the chosen layer does to one dependency of the chunk. */
export type DeclaredLinkMark = {
	/**  The dependency as the applied list spells it, or the game's list for a removal. */
	path: string,
	change: LinkChange,
};

/**  The dependencies a body adds to and removes from a chunk's link list. ADR-0050. */
export type DeclaredLinks = {
	/**  The `links` items, in order. */
	add: string[],
	/**  The `-links` items, in order. */
	remove: string[],
};

/**  One row a declaration of the chosen layer touches. */
export type DeclaredMark = {
	/**  The object's path hash, `0x` and eight hex digits. */
	entry: string,
	/**  The row's hash path. Empty where the declared path reaches no row. */
	path: string,
	/**  The property path the declaration names, as a module action takes it. */
	property: string,
	/**  The index of the module holding the declaration. */
	module: number,
	moduleName: string | null,
	sign: DeclaredSign,
	/**  The declaration sets a whole list or map, which no later change of the game's reaches. */
	whole: boolean,
	/**  The game-copy reference the declaration's value is, `<entry>:<property path>`. */
	reference: string | null,
	/**
	 *  The game's value as a declaration spells it. Absent where the game holds none, and
	 *  for a value that does not render.
	 */
	game: string | null,
};

/**  One module of a manifest. */
export type DeclaredModule = {
	/**  The module's position in `modules`, zero-based. */
	index: number,
	/**  The module's own name, where the manifest spells one. */
	name: string | null,
	/**  The comment lines directly above the module, without their `#`. */
	note: string | null,
	selector: ModuleSelector,
	/**  The chunk a `target` module edits, as spelled. */
	target: string | null,
	/**  The path hash of the chunk a `target` module edits, 16 lowercase hex digits. */
	targetHash: string | null,
	/**
	 *  The source file holding the module's edits. The spans of its entries and keys are
	 *  `None`, since they sit in that file.
	 */
	source: string | null,
	/**  The override files the module names, layer-relative. */
	overrides: string[],
	/**  The dependencies a `target` module adds to and removes from its chunk, over every edit. */
	links: DeclaredLinks,
	/**  The module's first line. */
	span: LineSpan | null,
	entries: DeclaredEntry[],
};

/**  The module a declared document's new keys join. ADR-0048. */
export type DeclaredModuleChoice = 
/**  The last `entries` module naming the entry, else the last module, else a new one. */
{ kind: "auto" } | 
/**  The `entries` module at `index` of `modules`. */
{ kind: "index"; index: number } | 
/**  A new trailing module, which the next key written makes, holding `name`. */
{ kind: "new"; name: string | null };

/**  One module of the chosen layer's manifest. */
export type DeclaredModuleSummary = {
	/**  The module's index in `modules`. */
	index: number,
	name: string | null,
	/**  An `entries` module, which takes new keys. A `target` module does not. */
	takesKeys: boolean,
};

/**  Every declaration of one object, with the path they share. */
export type DeclaredObject = {
	/**  The object's path, or its hash when no table names it. */
	path: string,
	/**  In archive order, and in the game index's tree order within one archive. */
	declarations: ObjectDeclaration[],
};

/**  What an `objects` binding does to one object. */
export type DeclaredObjectEdit = 
/**  A copy of the entry `source`, with the path the hashtables give a hash-spelled one. */
{ kind: "clone"; source: string; knownSource: string | null } | 
/**  A new object of `class`, with the name the hashtables give a hash-spelled one. */
{ kind: "construct"; class: string; knownClass: string | null } | 
/**  The object's removal. */
{ kind: "remove" };

/**  What a declaration of the chosen layer does to one object of the chunk. */
export type DeclaredObjectMark = {
	/**  The object's path hash, `0x` and eight hex digits. */
	entry: string,
	change: ObjectChange,
};

/**  What declares each of a set of object hashes, beside the slot the index is in. */
export type DeclaredObjects = {
	/**  Off `Ready`, only the open document's own objects are in `objects`. */
	index: ObjectIndexStatus,
	/**  By the object's hash, `0x` and eight hex digits. A hash nothing declares is absent. */
	objects: { [key in string]: DeclaredObject },
};

/**  The sign of a declared key. */
export type DeclaredSign = "set" | "add" | "remove";

/**  What a declared document says beside its rows. */
export type DeclaredState = {
	/**  The layer an edit writes to. */
	layer: string,
	/**  The module of `layer` a new key joins. */
	module: DeclaredModuleChoice,
	/**  The modules of `layer` in execution order. */
	modules: DeclaredModuleSummary[],
	/**  The project's layers in build order. */
	layers: string[],
	/**  The rows a declaration of `layer` touches. */
	marks: DeclaredMark[],
	/**  The objects a declaration of `layer` creates or removes. */
	objects: DeclaredObjectMark[],
	/**  The dependencies a declaration of `layer` adds or removes. */
	links: DeclaredLinkMark[],
	/**  What the last apply reported, over every layer. */
	diagnostics: DeclaredDiagnostic[],
};

/**
 *  Whether a declared document takes edits, the project's "Use game data declarations".
 * 
 *  Off draws the same applied tree and marks, read-only.
 */
export type Declaring = 
/**  An edit lands as a declaration in the chosen layer. */
"on" | 
/**  The document takes no edit. */
"off";

/**
 *  One patcher binary as a decoded token presents it: the checksum, and the
 *  build date as a full timestamp.
 */
export type DecodedBinary = {
	hash: string,
	/**  RFC 3339, UTC, when the build date was a date. */
	built: string | null,
};

/**
 *  A token read against this build's tables, for a reader.
 * 
 *  Each enum is `None` for a number this build does not know, with the
 *  verdict's number kept beside it, so a token from a newer manager reads as
 *  far as it can and never as an error.
 */
export type DecodedIncident = {
	/**  RFC 3339, UTC, to the minute, or `None` when the token carried no time. */
	endedAt: string | null,
	/**  `1.14.0`. */
	manager: string,
	/**  `16.16.804.9184`. */
	game: string | null,
	verdict: VerdictKind | null,
	/**
	 *  The verdict's number as the token carries it, for one this build does
	 *  not know.
	 */
	verdictCode: number,
	/**  The verdict's title, or `Verdict 17` for one this build does not know. */
	title: string,
	consequence: Consequence | null,
	origin: OriginKind | null,
	overlay: OverlayOutcome | null,
	scan: ScanMode | null,
	launch: LaunchKind | null,
	injected: boolean,
	hostElevated: boolean,
	phase: GamePhase | null,
	ending: Ending,
	durationSecs: number | null,
	/**  Each code with what this build's table says about it. */
	codes: EvidenceCode[],
	lastLoadStep: number | null,
	missingHash: string | null,
	subject: string | null,
	suspects: string[],
	skipped: SkippedArchive[],
	redirectedCount: number,
	enabledCount: number,
	/**  The hook DLL that ran, with its build date read out. */
	dll: DecodedBinary | null,
	/**  The injection host that ran. */
	host: DecodedBinary | null,
	/**  Whether both binaries are the ones the sender's manager build shipped. */
	patcherOk: boolean | null,
	scanStatus: ScanStatus | null,
	/**  The status code as the scan reported it, beside the reading. */
	scanStatusCode: string | null,
	failure: string | null,
	overlayDetail: string | null,
};

/**  Parsed representation of a `ltk://install` deep-link URL. */
export type DeepLinkInstallRequest = {
	url: string,
	name: string | null,
	author: string | null,
	source: string | null,
	/**
	 *  The host outside the allowlist, or `None` where the allowlist covers it.
	 * 
	 *  Stamped by [`handle_single`] rather than by parsing, since the trust is a
	 *  property of the reader's settings and not of the URL.
	 */
	untrustedDomain: string | null,
};

/**  A `ltk://` deep link, as the route named in it. */
export type DeepLinkRequest = {
	kind: "install",
} & DeepLinkInstallRequest | {
	kind: "settings",
} & DeepLinkSettingsRequest;

/**  Parsed representation of a `ltk://settings` deep-link URL. */
export type DeepLinkSettingsRequest = {
	/**  The public setting or group id the page opens on, as `?focus=` carries it. */
	focus: string,
};

/**  One `NAME=VALUE` of the define list. */
export type Define = {
	name: string,
	value: string,
	/**  The last stage that set it. */
	source: DefineSource,
};

/**
 *  The stages the define list is built from, in the order the engine runs them, later
 *  winning.
 */
export type DefineSource = 
/**  `StaticMaterialDef.shaderMacros`. */
"material" | 
/**  `CustomShaderDef.featureDefines`, all of them. */
"feature" | 
/**  A compile-time static switch, `1` on and `0` off. */
"switch" | 
/**  `StaticMaterialPassDef.shaderMacros`. */
"pass" | 
/**  Set by the engine for the emitter that draws an engine particle shader. */
"emitter";

/**  One dependency a `PROP` names, as its path and its brex spelling. */
export type Dependency = {
	/**  The archive path as the file writes it. */
	path: string,
	/**
	 *  The path in brex, which folds the repeated terms of a packed bin name. Absent where
	 *  the path repeats nothing.
	 */
	packed: string | null,
};

/**  An edit of the header's dependency list. ADR-0050. */
export type DependencyEdit = 
/**
 *  Put the dependency `text` names at `index`, the end where it is absent, answering
 *  [`EditOutcome::Index`]. [`BinDocument::insert_dependency`].
 */
{ kind: "insert"; index: number | null; text: string } | 
/**  Take the dependency at `index` out. [`BinDocument::remove_dependency`]. */
{ kind: "remove"; index: number } | 
/**  Move the dependency at `from` to `to`. [`BinDocument::move_dependency`]. */
{ kind: "move"; from: number; to: number } | 
/**
 *  Replace the dependency at `index` with the one `text` names.
 *  [`BinDocument::set_dependency`].
 */
{ kind: "set"; index: number; text: string } | 
/**  Take back the chosen layer's removal of `path`. [`BinDocument::restore_dependency`]. */
{ kind: "restore"; path: string };

/**
 *  Categories derived from a mod's contents. Each list is de-duplicated and
 *  sorted. Champions hold display names (e.g. `"Aatrox"`); maps and tags hold
 *  well-known slugs (e.g. `"summoners-rift"`, `"champion-skin"`).
 */
export type DerivedCategorization = {
	champions: string[],
	maps: string[],
	tags: string[],
	/**
	 *  The champion the mod contributes most content to, of [`Self::champions`].
	 * 
	 *  Weighted by chunk paths on the precise path and by per-WAD override
	 *  counts on the coarse one, so a mod that edits one champion and spills a
	 *  little into two others names the one it is actually a skin for. `None`
	 *  for a report analysed before this was recorded, and for a mod with no
	 *  champions at all.
	 */
	primaryChampion?: string | null,
};

/**  Full diagnostic report returned by `run_diagnostics`. */
export type DiagnosticReport = DiagnosticReport_Serialize | DiagnosticReport_Deserialize;

/**  Full diagnostic report returned by `run_diagnostics`. */
export type DiagnosticReport_Deserialize = {
	/**  ISO-8601 UTC timestamp. */
	generatedAt: string,
	/**  Manager version (matches `Cargo.toml`). */
	appVersion: string,
	/**  All checks in display order. */
	checks: Check_Deserialize[],
};

/**  Full diagnostic report returned by `run_diagnostics`. */
export type DiagnosticReport_Serialize = {
	/**  ISO-8601 UTC timestamp. */
	generatedAt: string,
	/**  Manager version (matches `Cargo.toml`). */
	appVersion: string,
	/**  All checks in display order. */
	checks: Check_Serialize[],
};

/**  The wiki's documentation for one class or one property. Each part is markdown. */
export type Doc = {
	/**  The main text. Absent when the entry has only notes or examples. */
	description: string | null,
	/**  Short caveats, one paragraph each. */
	notes: string[],
	/**  Worked examples, one block each. */
	examples: string[],
};

/**  Fields to change on a mod's metadata. `None` leaves a field untouched. */
export type EditModMetadataArgs = {
	displayName: string | null,
	tags: string[] | null,
	champions: string[] | null,
	maps: string[] | null,
	setThumbnailPath?: string | null,
	removeThumbnail?: boolean | null,
};

/**  What a landed [`BinEdit`] answers beside the change itself. */
export type EditOutcome = 
/**  Nothing beyond the change. */
{ kind: "done" } | 
/**  The value a patched leaf held. */
{ kind: "previous"; value: LeafValue } | 
/**  A created object's path hash, `0x` and eight hex digits. */
{ kind: "object"; entry: string } | 
/**  The path of an inserted or moved item, or of a rekeyed map entry. */
{ kind: "path"; path: string } | 
/**  The position of an inserted dependency. */
{ kind: "index"; index: number } | 
/**  The declared state after a module action. */
{ kind: "declared"; state: DeclaredState };

/**  Why a leaf edit's value does not fit the node it addresses. */
export type EditRejection = 
/**  The node holds no value an edit sets: a container, a struct or an absent optional. */
{ reason: "notALeaf" } | 
/**  The value is of another kind than the leaf. */
{ reason: "wrongKind"; kind: PropertyKind } | 
/**  An integer the leaf's kind does not hold. */
{ reason: "outOfRange"; kind: PropertyKind } | 
/**  A float that is NaN or an infinity. */
{ reason: "notFinite" } | 
/**  A vector or a matrix of another number of components than the leaf holds. */
{ reason: "wrongLength"; expected: number } | 
/**  A hash text that is empty, or hex of another width. */
{ reason: "malformedHash" } | 
/**  The node holds no properties: a leaf, a container, or a null pointer. */
{ reason: "notAHolder" } | 
/**  The path ends in no property of a holder. */
{ reason: "notAProperty" } | 
/**  The holder writes the field already. */
{ reason: "propertyExists" } | 
/**  The schema declares no such field on the holder's class or its bases. */
{ reason: "undeclaredField" } | 
/**  An embed names no class. */
{ reason: "missingClass" } | 
/**  The kinds build no value: a container of nothing, or a kind a container cannot hold. */
{ reason: "invalidShape" } | 
/**  The node holds no items: it is no list, map or option. */
{ reason: "notAList" } | 
/**  The path ends in no item of a list, a map or an option. */
{ reason: "notAnItem" } | 
/**  The node is no pointer. */
{ reason: "notAPointer" } | 
/**  Another entry of the map holds the key. */
{ reason: "keyExists" } | 
/**  A map entry names no key. */
{ reason: "missingKey" } | 
/**  The option or the pointer holds a value already. */
{ reason: "valueHeld" } | 
/**  The list holds no such position. */
{ reason: "noSuchIndex" } | 
/**  A dependency path that is empty. */
{ reason: "emptyPath" } | 
/**  A dependency typed in brex that does not expand to one path. */
{ reason: "malformedBrex" } | 
/**  The list names the dependency already. */
{ reason: "dependencyExists" } | 
/**
 *  The path runs through a field no table names, or a key a map holds twice, which no
 *  declaration spells. ADR-0042.
 */
{ reason: "namelessPath" } | 
/**  No declaration expresses the edit. ADR-0042. */
{ reason: "undeclarable" } | 
/**
 *  The schema gives no type for a property the game's copy omits, as at a game build
 *  newer than the meta database. ADR-0042.
 */
{ reason: "untypable" } | 
/**  The chunk holds an object of that name. */
{ reason: "objectExists" } | 
/**  The text is no value a copy put on the clipboard. */
{ reason: "notACopy" } | 
/**  The holder takes no item of the copied value's class. */
{ reason: "foreignClass" };

/**  One key of the skin's resolver, and the system it stands for. */
export type EffectSystem = {
	/**  The key, `0x` and eight hex digits. */
	key: string,
	/**  The `VfxSystemDefinitionData` object, `0x` and eight hex digits. */
	system: string,
	/**  The linked file declaring the system, and none where the skin's own document does. */
	source: AssetRef | null,
};

/**  How the game ended, as far as anything said. */
export type Ending = {
	/**
	 *  The Riot Client's reason: `Exit`, `Interrupt`, `Timeout`, `Unknown`, or a
	 *  spelling the crate does not know. `None` on the Classic launch flow.
	 */
	exitReason: string | null,
	exitCode: number | null,
	/**
	 *  Whether `last_crash` fell inside the game's window. `None` when the
	 *  marker was not read.
	 */
	crashed: boolean | null,
};

/**  A pass the engine draws with its own shader rather than a material's. */
export type EnginePass = 
/**
 *  The pass a skinned submesh draws with where its skin names no material, with
 *  `LIT_UBER` translated, over the shader cache `document` resolves against.
 */
{ kind: "defaultSkinned"; document: BinDocumentId } | 
/**
 *  An engine particle shader's pass for the defines an emitter sets, over the shader
 *  cache `document` resolves against, and the install's alone where it is none.
 */
{ kind: "particle"; document: BinDocumentId | null; shader: ParticleShader; defines: ParticleDefine[] };

/**
 *  Which [`AppError`] a failure was, as a name that outlives its message.
 * 
 *  A message is for a reader and can be empty. This is the part a consumer
 *  switches on, so it survives being recorded, stored and read back long after
 *  the error value is gone. The Tauri shell maps it to its own `ErrorCode`, and
 *  a CLI could map the same names to exit codes.
 */
export type ErrorKind = "IO" | "SERIALIZATION" | "MODPKG" | "LEAGUE_NOT_FOUND" | "INVALID_PATH" | "MOD_NOT_FOUND" | "VALIDATION_FAILED" | "INTERNAL_STATE" | "OTHER" | "WORKSHOP_NOT_CONFIGURED" | "PROJECT_NOT_FOUND" | "PROJECT_ALREADY_EXISTS" | "PACK_FAILED" | "FANTOME" | "WAD_ERROR" | "WAD_BUILDER_ERROR" | "PATCHER" | "LAUNCHER" | "ZIP_ERROR" | "SCHEMA_VERSION_TOO_NEW" | "WORKSHOP" | "HASHTABLE" | "PREVIEW" | "BIN_DOCUMENT" | "OVERLAY" | "UNTRUSTED_DOMAIN";

/**  What a clip event does, for the kinds a viewport plays, and nothing for the rest. */
export type EventKind = 
/**  `SubmeshVisibilityEventData`: submeshes shown and hidden from the start frame on. */
{ kind: "submeshVisibility"; 
/**  `mShowSubmeshList`. */
show: HashRef[]; 
/**  `mHideSubmeshList`. */
hide: HashRef[] } | 
/**  `ParticleEventData`: a system spawned on a joint at the start frame. */
{ kind: "particle"; 
/**  `mEffectKey`, `0x` and eight hex digits, which the skin's resolver maps. */
effectKey: string; 
/**  `mEffectName`, what the author called it. */
effectName: string; 
/**  `mParticleEventDataPairList`, one spawn per pair. */
spawns: EventSpawn[]; 
/**  `mIsLoop`. */
isLoop: boolean; 
/**  `mIsKillEvent`, which stops the effect of the key rather than spawning one. */
isKill: boolean; 
/**  `scale`, which the meta defaults to one. */
scale: number | null } | 
/**  `JointSnapEventData`: one joint stands where another does, from the start frame on. */
{ kind: "jointSnap"; 
/**  `mJointNameToOverride`, the joint moved, and none for an event naming no joint. */
joint: HashRef | null; 
/**  `mJointNameToSnapTo`, the joint it stands on, and none for an event naming no joint. */
snapTo: HashRef | null; 
/**  `offset`, in the frame of the joint stood on. */
offset: [(number | null), (number | null), (number | null)] } | 
/**  `ConformToPathEventData`: the joints a mask weighs follow the unit's path over the span. */
{ kind: "conformToPath"; 
/**  `mMaskDataName`, the joints that conform, and none for an event naming no mask. */
mask: KeyRef | null; 
/**  `mBlendInTime`, seconds the conforming eases in over. */
blendIn: number | null; 
/**  `mBlendOutTime`, seconds it eases out over. */
blendOut: number | null } | 
/**  Any other kind, which the viewport draws nothing for. */
{ kind: "other" };

/**  One pair of a particle event: the joint the system rides, and the joint it aims at. */
export type EventSpawn = {
	/**  `mBoneName`, and none for a pair riding the skeleton's own origin. */
	bone: HashRef | null,
	/**  `mTargetBoneName`, and none for a pair aiming at nothing. */
	targetBone: HashRef | null,
};

/**  One line the verdict rests on. */
export type Evidence = {
	/**  Seconds into the game where the source has one, else the wall clock. */
	at: string,
	source: EvidenceSource,
	line: string,
	/**  The lines under a game record with no columns of their own. */
	detail?: string[],
	code: EvidenceCode | null,
};

/**  What the table says about a code on an evidence line. */
export type EvidenceCode = {
	id: string,
	/**  The kind column, or `None` when the table has no row. */
	kind: string | null,
	meaning: string | null,
	mark: EvidenceMark | null,
};

/**
 *  How firm a row's reading is, which is a claim about this table and no more.
 * 
 *  It hedges the one sentence that reads the code and nothing else. What a
 *  verdict cost the game is a fact the manager observed, so the mark never
 *  grades it - see [`Consequence`](super::incident::Consequence).
 */
export type EvidenceMark = 
/**  The reading is a fact, and the sentence states it as one. */
"confirmed" | 
/**  The reading is probable, and the sentence says `probably`. */
"inferred";

/**  Where a line of evidence came from. */
export type EvidenceSource = "patcher" | "host" | "dll" | "game" | "client";

/**  What an extract does about a file already sitting where one would land. */
export type ExistingFiles = 
/**  Leave it, and count it. The dialog's default, and not the crate's. */
"skip" | 
/**  Write over it. */
"replace";

/**  Progress of a mod export, emitted per mod. */
export type ExportProgress = {
	current: number,
	total: number,
	currentMod: string,
};

/**
 *  Which of the library's mods an export writes.
 * 
 *  Every profile holds every mod, so the only scope narrower than the library
 *  is what the active profile has switched on.
 */
export type ExportScope = 
/**  What the active profile has on. */
"enabled" | 
/**  Every mod in the library. */
"all";

/**  What an export writes: loose archives, or one zip holding them. */
export type ExportShape = 
/**  One archive per mod, into a directory. */
"folder" | 
/**  Every archive inside one `.zip` file. */
"zip";

/**  What an export wrote, and what it had to leave behind. */
export type ExportSummary = {
	/**  How many mods reached the destination. */
	exported: number,
	/**  Mods with no archive to copy, named as the library names them. */
	skipped: string[],
	/**  What the export wrote, for a surface that offers to reveal it. */
	destination: string,
};

/**  One kind of file an extract wrote, and how many. */
export type ExtractKindCount = {
	kind: WorkshopFileKind,
	count: number,
};

/**  Where each file of an extract lands under the destination. */
export type ExtractLayout = 
/**  Each file at its game path, which is what a repack reads back. */
"paths" | 
/**  Every file in the destination by its name alone. */
"flat";

/**  Everything one extract needs beyond the targets themselves. */
export type ExtractOptions = {
	/**  The folder to write into. Made if it is not there. */
	destination: string,
	layout?: ExtractLayout,
	/**
	 *  Put each archive's files under a folder of the archive's own name,
	 *  which is the layout a layer holds.
	 */
	perArchiveFolder?: boolean,
	existing?: ExistingFiles,
	/**
	 *  Read the archive's own bins for names no hash table holds.
	 * 
	 *  Off, because a synced cache already names a game archive, and the scan
	 *  reads every bin in one to find the handful it does not. Worth its cost
	 *  where the cache is missing and the bins are the only names there are.
	 */
	recoverNames?: boolean,
	/**  The browser's filter chips. `None` writes every kind. */
	kinds?: WorkshopFileKind[] | null,
};

/**
 *  What an extract will write, before it writes anything.
 * 
 *  The dialog's summary line reads this, so a user sees the count, the size
 *  and the archives before choosing a destination.
 */
export type ExtractPlan = {
	files: number,
	/**  Uncompressed bytes, which is what lands on disk. */
	bytes: number,
	/**  The root-relative archives the run reads, in the order it does. */
	archives: string[],
};

/**
 *  Progress of an extract of game chunks to disk.
 * 
 *  One extract runs over any number of archives, so `current` and `total`
 *  count the whole run rather than the archive being read. The extractor
 *  reports every chunk it finishes, which is tens of thousands for a large
 *  archive, so the emitter throttles rather than sending one of these each
 *  time.
 */
export type ExtractProgress = {
	current: number,
	total: number,
	/**  The chunk just written, or its hex hash when nothing names it. */
	currentPath: string | null,
	/**  Bytes written so far across the whole run. */
	bytes: number,
	/**  The `DATA/FINAL`-relative archive being read. */
	archive: string,
};

/**  What an extract did, summed over every archive it read. */
export type ExtractSummary = {
	extracted: number,
	skippedExisting: number,
	skippedByFilter: number,
	/**
	 *  Chunks the index named that the archive turned out not to hold, which
	 *  means the two disagree rather than that anything failed.
	 */
	missing: number,
	bytesWritten: number,
	/**  Written files by the kind their bytes identify as, most first. */
	byKind: ExtractKindCount[],
	/**  The cancel flag was set, so this is a part of what was asked for. */
	cancelled: boolean,
	/**  Names the archives' own bins gave chunks no hash table knew. */
	recovered: number,
	/**
	 *  Chunks written under a name their resolved path did not give, because a
	 *  directory held that name or another chunk claimed it first.
	 */
	renamed: number,
	/**
	 *  Chunks whose resolved path the extraction refused to write, so nothing
	 *  landed for them. A hash table naming a path that escapes the output
	 *  directory is the usual cause.
	 */
	rejected: number,
	/**
	 *  Chunks another chunk's path claimed first that went unwritten. Zero
	 *  under a lossless naming policy, which renames them instead.
	 */
	duplicates: number,
	/**  The folder written into, for the report's **Open folder**. */
	destination: string,
};

/**  One row of the browser, as a thing to extract. */
export type ExtractTarget = 
/**
 *  One chunk, as a file row of the browser holds it.
 * 
 *  `path_hash` is what gets extracted. `path` and `size_bytes` are the
 *  row's own copy, and only shape the summary and the kind filter, so a
 *  stale row costs an off-by-one in a count rather than the wrong bytes.
 */
{ kind: "file"; wad: string; pathHash: string; path: string | null; sizeBytes: number } | 
/**  Every file at or below one directory of the folded index. */
{ kind: "dir"; path: string } | 
/**
 *  Every chunk of one archive.
 * 
 *  Read out of the archive rather than out of the index, because the fold
 *  keeps one copy of a chunk that several archives carry and drops the
 *  rest. An archive row means the archive, not the part of it the index
 *  happens to attribute to it.
 */
{ kind: "archive"; wad: string };

/**  One mod the migration could not convert. */
export type FailedConversion = {
	/**  The mod's index id, which is also the directory the uuid layout gave it. */
	id: string,
	/**  What to call the mod in the failure list, falling back to its id. */
	displayName: string,
	/**  Why it could not be moved, in the words the user reads. */
	error: string,
};

/**  A fantome-layout folder, as the conversion would read it. */
export type FantomeFolder = {
	displayName: string,
	suggestedName: string,
	author: string | null,
	version: string | null,
	/**  Whether `META/info.json` was there to read the metadata from. */
	hasInfo: boolean,
	wads: FolderWad[],
	/**  Whether a `RAW/` directory holds loose files. */
	hasRaw: boolean,
};

/**  Progress of a fantome import. */
export type FantomeImportProgress = {
	stage: FantomeImportStage,
	/**
	 *  The unit being unpacked, as the archive names it: a WAD, or `RAW` for
	 *  the pass that unpacks everything the archive keeps outside one.
	 */
	currentItem: string | null,
	current: number,
	total: number,
};

/**
 *  Stage of a fantome import.
 * 
 *  Coarser than the stages `ltk_mod_project`'s importer reports: everything
 *  past the content is `Finalizing`, because none of it carries a count a bar
 *  could be drawn from. `Error` has no counterpart there at all, since a failed
 *  import returns rather than reporting, so the caller emits it.
 */
export type FantomeImportStage = "extracting" | "finalizing" | "complete" | "error";

/**  Metadata peeked from a .fantome archive without extracting content. */
export type FantomePeekResult = {
	name: string,
	author: string,
	version: string,
	description: string,
	wadFiles: string[],
	suggestedName: string,
};

/**  One field's type over one span of builds. */
export type FieldRevision = {
	/**  The first content build the revision holds for. */
	from: number,
	/**  The last content build it holds for, inclusive. Open where absent. */
	to: number | null,
	/**  The patch that shipped `from`, absent where the database names none that early. */
	patch: string | null,
	/**  Absent for a type this build cannot map. */
	shape: KindShape | null,
};

/**  One field of a class: its name, its type at the card's build, and every revision. */
export type FieldSchema = {
	/**  `0x` and eight hex digits. */
	hash: string,
	/**  The field as the database names it. */
	name: string | null,
	/**
	 *  The type at the card's build. Absent where no revision covers the build, and
	 *  where the revision names a type this build cannot map.
	 */
	declared: KindShape | null,
	/**  The declared class of an embed, pointer, or container item. */
	classHash: string | null,
	/**  The constructor default as lossless JSON, absent when the schema has none. */
	defaultValue: string | null,
	/**  The base class that declares the field, absent where the class itself does. */
	owner: ClassRef | null,
	/**  Oldest first. */
	revisions: FieldRevision[],
};

/**
 *  What one fix run did to a file, as against how much of it.
 * 
 *  The counts beside this say how much a rule changed. This says whether the
 *  file survived, which is what an archive edit has to know before it can state
 *  the repair as a chunk write.
 */
export type FileChange = "written" | "removed";

/**  What one fix run did to one file. */
export type FileOutcome = {
	layer: string,
	/**  POSIX-style and relative to the layer root. */
	path: string,
	applied: number,
	skipped: number,
	/**
	 *  Whether the file is still there.
	 * 
	 *  Defaulted for a report recorded before a repair could delete anything,
	 *  which is every report written before this field existed.
	 */
	change?: FileChange,
};

/**
 *  What a repair would change, in the words a row draws.
 * 
 *  The type it moves the property to is [`Problem::mismatch`] rather than a
 *  field here, because a problem no rule can repair still has one to draw.
 */
export type FixPreview = FixPreview_Serialize | FixPreview_Deserialize;

/**
 *  What a repair would change, in the words a row draws.
 * 
 *  The type it moves the property to is [`Problem::mismatch`] rather than a
 *  field here, because a problem no rule can repair still has one to draw.
 */
export type FixPreview_Deserialize = {
	/**  What the values alone do not say, such as `3 items`. */
	note?: string | null,
	/**  The value now, rendered. `None` where a container draws its count instead. */
	before: string | null,
	/**  The value after, rendered. `None` for the same reason as `before`. */
	after: string | null,
};

/**
 *  What a repair would change, in the words a row draws.
 * 
 *  The type it moves the property to is [`Problem::mismatch`] rather than a
 *  field here, because a problem no rule can repair still has one to draw.
 */
export type FixPreview_Serialize = {
	/**  What the values alone do not say, such as `3 items`. */
	note?: string | null,
	/**  The value now, rendered. `None` where a container draws its count instead. */
	before: string | null,
	/**  The value after, rendered. `None` for the same reason as `before`. */
	after: string | null,
};

/**  What one fix run applied, skipped and wrote. */
export type FixReport = {
	applied: number,
	/**  Problems the file no longer matched, which the rules left alone. */
	skipped: number,
	/**  Paths this run wrote into the mod's own tables before hashing them. */
	namesKept: number,
	/**  The migration tables the run applied. */
	tables: string[],
	/**
	 *  The named problems a re-check still saw once the run had written.
	 * 
	 *  Read off the repaired tree in memory rather than by analyzing the
	 *  project a second time. Empty is the ordinary outcome.
	 */
	remaining: ProblemId[],
	files: FileOutcome[],
	/**  A file a rule could not finish, and why. */
	failed: string[],
};

/**  A folder the batch could not add, and why. */
export type FolderFailure = {
	path: string,
	message: string,
};

/**  What a folder picked with Open folder holds. */
export type FolderInspection = 
/**  Nothing at the path. */
{ kind: "missing" } | 
/**  A folder with a project config, ready to open. */
{ kind: "project"; project: WorkshopProject } | 
/**  A mod in fantome layout, such as a cslol-manager install. */
{ kind: "fantome"; layout: FantomeFolder } | 
/**  A folder whose subfolders are projects or fantome mods. */
{ kind: "parent"; projects: string[]; fantome: string[] } | 
/**  A folder with none of the above, which can become an empty project. */
{ kind: "plain"; suggestedName: string; displayName: string };

/**  One entry of a fantome folder's `WAD/` directory. */
export type FolderWad = {
	name: string,
	/**  A packed archive, which the conversion unpacks, rather than a directory it moves. */
	packed: boolean,
};

/**  A map skin every game can be made to show. */
export type ForcibleMapSkin = {
	/**  The skin's `name`, which the setting stores. */
	name: string,
	/**  Each map archive holding a whole skin by that name, such as `Map11.wad.client`. */
	maps: string[],
};

/**
 *  Payload for the `patcher-game-attached` event: the DLL is in the game,
 *  which says nothing yet about whether the overlay went live.
 */
export type GameAttachedPayload = {
	/**  The game's process id, when a `dll` line named it. */
	pid: number | null,
};

/**  One subdirectory, folded through any chain of single-child directories. */
export type GameDirEntry = {
	/**  What [`GameIndex::read_dir`] takes to open this row, forward slashes. */
	path: string,
	/**  What the row reads: the folded chain of segments joined by `/`. */
	name: string,
	/**  Files at or below the directory. */
	fileCount: number,
};

/**  What one directory of the folded index holds. */
export type GameDirListing = {
	/**  Subdirectories, sorted by name. */
	dirs: GameDirEntry[],
	/**  Files directly under this directory, sorted by name. */
	files: GameFileEntry[],
};

/**  One file of the folded index, in the shape a single archive reads back. */
export type GameFileEntry = {
	/**  Chunk path hash as 16 lowercase hex digits. */
	pathHash: string,
	/**  Resolved chunk path, or `None` when no hash table names it. */
	path: string | null,
	/**  Uncompressed chunk size. */
	sizeBytes: number,
	/**
	 *  The archive the chunk was read from, relative to its source's root.
	 * 
	 *  The fold drops every copy of a chunk after the first, so this names the
	 *  archive that copy came from and not every archive that carries it.
	 */
	wad: string,
};

/**
 *  One file the full search matched, shaped as an entry a file tree can hold.
 * 
 *  The pattern is matched over the full path, and the marked runs arrive
 *  split at the basename: `name_ranges` are byte offsets into `name`, and
 *  `path_ranges` are byte offsets into the directory prefix of `path`.
 */
export type GameFindHit = {
	/**  Chunk path hash as 16 lowercase hex digits. */
	pathHash: string,
	/**  Resolved path with forward slashes, or `None` when no hash table names the chunk. */
	path: string | null,
	/**  The path's basename, or the hash when no hash table names the chunk. */
	name: string,
	/**  The archive the chunk was read from, relative to its source's root. */
	wad: string,
	/**  Uncompressed chunk size. */
	sizeBytes: number,
	nameRanges: ([number, number])[],
	pathRanges: ([number, number])[],
};

/**  What one full search of the folded index found. */
export type GameFindResult = {
	/**  Every matching row in tree order, capped at [`FIND_LIMIT`]. */
	hits: GameFindHit[],
	/**  How many files matched in all, counted on past the cap. */
	total: number,
	/**
	 *  A newer search started before this one finished, so it gave up early.
	 * 
	 *  Its rows are whatever it had found, which is not the whole answer. The
	 *  caller is expected to be showing the newer pattern by now.
	 */
	superseded: boolean,
	/**  No hash table named a single chunk, so only a hash can match. */
	unnamed: boolean,
};

/**  What a built index holds. */
export type GameIndexStats = {
	/**  Archives merged, including any that failed to read. */
	archives: number,
	/**  Files after deduplication. */
	files: number,
	/**  Directories, not counting the root. */
	dirs: number,
};

/**  The facts the game log gives about the game itself. */
export type GameInfo = {
	version: string,
	contentVersion: string,
	logPath: string,
	/**  The install root the game ran from, as its command line named it. */
	gameBaseDir: string | null,
};

/**
 *  Payload for the `patcher-game-overlay` event: what the DLL said about the
 *  overlay after it attached.
 */
export type GameOverlayPayload = {
	outcome: OverlayOutcome,
};

/**  How far the game got, as its log says. */
export type GamePhase = 
/**  No log was read. */
"unknown" | 
/**  The loading screen never finished. */
"loading" | 
/**  `Loading Ended` was written. */
"in-game" | 
/**  The game ended the way it should. */
"torn-down";

/**
 *  One row a search matched, with the runs its two lines mark.
 * 
 *  Marked runs are byte offsets into `name` and `path`, which the palette
 *  slices to lift the matched characters out of the rest.
 */
export type GameSearchHit = {
	/**  Chunk path hash as 16 lowercase hex digits. */
	pathHash: string,
	/**  The path's basename, or the hash when no hash table names the chunk. */
	name: string,
	/**  The directory holding it, empty at the root and for an unnamed chunk. */
	path: string,
	/**  The archive the chunk was read from, relative to its source's root. */
	wad: string,
	/**  0 is a name the query opens, 1 a name holding it, 2 a match reaching the directory. */
	band: number,
	score: number | null,
	nameRanges: ([number, number])[],
	pathRanges: ([number, number])[],
};

/**  What one search of the folded index found. */
export type GameSearchResult = {
	/**  The best rows, best first, capped at [`SEARCH_LIMIT`]. */
	hits: GameSearchHit[],
	/**  How many files matched in all, which the cap trimmed. */
	total: number,
	/**
	 *  A newer search started before this one finished, so it gave up early.
	 * 
	 *  Its rows are whatever it had found, which is not the whole answer. The
	 *  caller is expected to be showing the newer query by now.
	 */
	superseded: boolean,
	/**
	 *  No hash table named a single chunk, so only a hash can match.
	 * 
	 *  An install whose names never resolved answers every path query with
	 *  nothing, which reads exactly like an install that holds no match. The
	 *  caller says which of the two it is.
	 */
	unnamed: boolean,
};

/**  One chunk of a WAD archive. */
export type GameWadEntry = {
	/**  Chunk path hash as 16 lowercase hex digits. */
	pathHash: string,
	/**  Resolved chunk path, or `None` when no hashtable knows the hash. */
	path: string | null,
	/**  Uncompressed chunk size. */
	sizeBytes: number,
};

/**  One WAD archive in a game install. */
export type GameWadSummary = {
	/**
	 *  Path relative to the source's archive root with forward slashes, e.g.
	 *  `Champions/Aatrox.wad.client` or `rcp-fe-lol-loot/assets.wad`.
	 */
	name: string,
	/**  Archive file size on disk, or 0 when it cannot be read. */
	sizeBytes: number,
};

/**  Which way a read of GitHub failed, as the remedy it has. */
export type GitHubErrorKind = 
/**  GitHub was never reached. Waiting for a connection is the remedy. */
"OFFLINE" | 
/**  The address has spent its unauthenticated quota. Waiting is the remedy. */
"RATE_LIMITED" | 
/**  The request went out and what came back is not what was asked for. */
"HTTP";

/**  Which of the things GitHub publishes a read was after. */
export type GitHubFeed = "RELEASES" | "ANNOUNCEMENTS" | "NOTICES";

/**  Progress of a git repository import. */
export type GitImportProgress = {
	stage: GitImportStage,
	message: string | null,
};

/**  Stage of a git repository import. */
export type GitImportStage = "downloading" | "extracting" | "complete" | "error";

/**  One entry of `mClipDataMap`, of any kind of `ClipBaseData`. */
export type GraphClip = {
	/**  The clip's key as the tables name it, and its hash where none does. */
	name: string,
	/**  The key, `0x` and eight hex digits. */
	hash: string,
	/**  The clip's class as the tables name it, and its hash where none does. */
	class: string,
	/**  `mAnimationResourceData.mAnimationFilePath`, which an atomic clip alone names. */
	animation: NamedAsset | null,
	/**  `mTrackDataName`. */
	track: KeyRef | null,
	/**  `mMaskDataName`. */
	mask: KeyRef | null,
	/**  `mSyncGroupDataName`. */
	syncGroup: KeyRef | null,
	/**  `mTickDuration`, seconds per tick, which an atomic clip alone sets. */
	tickDuration: number | null,
	/**  `mEventDataMap`, in map order. */
	events: ClipEvent[],
	/**  The clips this one plays, in its kind's field order. */
	children: KeyRef[],
	/**
	 *  `mValue` of each pair of a parametric clip, one per child in the same order, and
	 *  empty for every other kind.
	 */
	parameters: (number | null)[],
	/**  `mAnimationInterruptionGroupNames`. */
	interruptionGroups: string[],
	/**  `mFlags`. */
	flags: number,
};

/**
 *  What preserving a mod's names at import found.
 * 
 *  Recorded on the entry rather than only logged: `unharvestable` is what
 *  tells a mod that preserved cleanly from one that arrived already lossy,
 *  and that distinction should outlive a log rotation.
 */
export type HarvestSummary = {
	/**
	 *  Names the archive gained on the way in. Zero means every recoverable
	 *  name was already declared or covered by the community tables.
	 */
	namesAdded: number,
	/**
	 *  Chunks with no recoverable name: hex-named, and named by nothing the
	 *  harvest could read.
	 */
	unharvestable: number,
};

/**
 *  A hash a bin names something outside the graph by, such as a submesh or a joint.
 * 
 *  The tables name a few of them. A viewport matches the hash against the names the `.skn`
 *  or the `.skl` spells, which is how the engine reaches them too.
 */
export type HashRef = {
	/**  The hash as the tables name it, and its hex where none does. */
	name: string,
	/**  The hash, `0x` and eight hex digits. */
	hash: string,
};

/**  What the shared hashtable cache currently holds. */
export type HashtableCacheStatus = {
	/**  Absolute cache directory. */
	dir: string,
	/**  Manifest generation time (RFC 3339), or `None` when the cache is empty. */
	generatedAt: string | null,
	/**  Present tables, in [`Table::ALL`] order. */
	tables: HashtableStatus[],
	/**  Ids from [`Table::ALL`] absent from the manifest. */
	missing: string[],
	/**
	 *  The meta schema database a check would read.
	 * 
	 *  The cached copy where a sync has installed one, and the snapshot this
	 *  build ships otherwise, so it is never absent.
	 */
	schema: MetaSchemaVersion,
};

/**  One present table in a [`HashtableCacheStatus`]. */
export type HashtableStatus = {
	/**  Stable table id, e.g. `game`. */
	id: string,
	/**  Active `.lhdb` filename from the manifest. */
	file: string,
	/**
	 *  The release this table was published in, e.g. `2026-07-10`.
	 * 
	 *  Per table rather than per cache: a sync only installs what changed, so
	 *  two tables in one cache can be of different vintages.
	 */
	version: string,
	/**  Entry count recorded in the manifest. */
	entries: number,
	/**  On-disk size of the active file, or 0 when it cannot be read. */
	sizeBytes: number,
	/**  Repository this table's inputs came from, e.g. `CommunityDragon/Data`. */
	sourceRepo: string | null,
	/**  Commit of that repository the inputs were taken at. */
	sourceCommit: string | null,
};

/**
 *  Progress of a hashtable sync, as its tables stream in.
 * 
 *  Every figure describes the whole run rather than the table in flight, so a
 *  reader draws one bar for the sync instead of one that restarts per file.
 *  The tables are tens of megabytes each, so the emitter throttles rather than
 *  sending one of these per chunk.
 */
export type HashtableSyncProgress = {
	/**  Id of the table being fetched, e.g. `game`. */
	table: string,
	/**  Which table of the run this is, counting from 1. */
	current: number,
	/**  How many tables the run fetches. */
	total: number,
	/**  Bytes of the whole run written so far. */
	downloaded: number,
	/**
	 *  Bytes the whole run will write, absent against a release that recorded
	 *  no sizes.
	 */
	totalBytes: number | null,
};

/**  What a completed sync run changed. */
export type HashtableSyncReport = {
	/**  True when nothing needed installing. */
	upToDate: boolean,
	/**  Ids of the tables installed by this run. */
	installed: string[],
	/**  Remote table ids this build does not know. Skipped, never fatal. */
	unknownTables: string[],
	/**
	 *  Ids published in a `.hashdb` format this build cannot open. Skipped, so
	 *  the cache keeps serving what it already holds and only a newer app can
	 *  install these.
	 */
	unsupportedTables: string[],
	/**  Whether this run also installed a newer meta schema database. */
	schemaInstalled?: boolean,
};

/**  One table the published release has a version of that this cache does not. */
export type HashtableUpdate = {
	/**  Stable table id, e.g. `game`. */
	id: string,
	/**  The version the cache holds, absent when it holds none. */
	have: string | null,
	/**  The version the release publishes. */
	want: string,
};

/**  What a sync would install, asked without installing anything. */
export type HashtableUpdateCheck = HashtableUpdateCheck_Serialize | HashtableUpdateCheck_Deserialize;

/**  What a sync would install, asked without installing anything. */
export type HashtableUpdateCheck_Deserialize = {
	/**  True when a sync would install nothing. */
	upToDate: boolean,
	/**  The tables a sync would download, in manifest order. */
	behind: HashtableUpdate[],
	/**
	 *  How many bytes those add up to, absent against a release that recorded
	 *  no sizes.
	 */
	downloadBytes: number | null,
	/**  Remote table ids this build does not know. A sync skips them. */
	unknownTables: string[],
	/**
	 *  Ids published in a `.hashdb` format this build cannot open. Named apart
	 *  from [`behind`](Self::behind) because syncing cannot install them, so
	 *  counting them as pending updates would promise a fix that is not there.
	 */
	unsupportedTables: string[],
	/**
	 *  The meta schema database that is published, when it is not the cached
	 *  one.
	 * 
	 *  Apart from [`behind`](Self::behind), which is tables and is drawn
	 *  against them, but counted in [`up_to_date`](Self::up_to_date) because
	 *  one sync covers both.
	 */
	schemaBehind?: MetaSchemaVersion | null,
};

/**  What a sync would install, asked without installing anything. */
export type HashtableUpdateCheck_Serialize = {
	/**  True when a sync would install nothing. */
	upToDate: boolean,
	/**  The tables a sync would download, in manifest order. */
	behind: HashtableUpdate[],
	/**
	 *  How many bytes those add up to, absent against a release that recorded
	 *  no sizes.
	 */
	downloadBytes: number | null,
	/**  Remote table ids this build does not know. A sync skips them. */
	unknownTables: string[],
	/**
	 *  Ids published in a `.hashdb` format this build cannot open. Named apart
	 *  from [`behind`](Self::behind) because syncing cannot install them, so
	 *  counting them as pending updates would promise a fix that is not there.
	 */
	unsupportedTables: string[],
	/**
	 *  The meta schema database that is published, when it is not the cached
	 *  one.
	 * 
	 *  Apart from [`behind`](Self::behind), which is tables and is drawn
	 *  against them, but counted in [`up_to_date`](Self::up_to_date) because
	 *  one sync covers both.
	 */
	schemaBehind?: MetaSchemaVersion | null,
};

/**
 *  What a check ran against, and therefore what makes an old one stale.
 * 
 *  Per "The basis" in docs/ux/MOD_HEALTH.md.
 */
export type HealthCheckBasis = HealthCheckBasis_Serialize | HealthCheckBasis_Deserialize;

/**
 *  What a check ran against, and therefore what makes an old one stale.
 * 
 *  Per "The basis" in docs/ux/MOD_HEALTH.md.
 */
export type HealthCheckBasis_Deserialize = {
	/**  The installed game build, absent where none could be read. */
	build: string | null,
	/**  The manager version, which is what a migration table ships in. */
	manager: string,
	/**
	 *  What the shared hashtable cache held, absent where it held nothing.
	 * 
	 *  The cache's own generation stamp, which moves only when a sync installs
	 *  a table. A check taken against different tables was a claim about
	 *  different names, so a sync makes every verdict due again without waiting
	 *  for a game patch.
	 */
	tables?: string | null,
	/**
	 *  What the meta schema database held, absent where none was open.
	 * 
	 *  It decides `bin/property-type` outright, so a check taken against
	 *  another database was a claim about other types. The database's own bytes
	 *  rather than the stamp it carries, because the publisher restamps the
	 *  hash tables behind it on a schedule of its own - a database that has
	 *  gained two patches can still carry the stamp it was first published
	 *  under.
	 */
	schema?: string | null,
};

/**
 *  What a check ran against, and therefore what makes an old one stale.
 * 
 *  Per "The basis" in docs/ux/MOD_HEALTH.md.
 */
export type HealthCheckBasis_Serialize = {
	/**  The installed game build, absent where none could be read. */
	build: string | null,
	/**  The manager version, which is what a migration table ships in. */
	manager: string,
	/**
	 *  What the shared hashtable cache held, absent where it held nothing.
	 * 
	 *  The cache's own generation stamp, which moves only when a sync installs
	 *  a table. A check taken against different tables was a claim about
	 *  different names, so a sync makes every verdict due again without waiting
	 *  for a game patch.
	 */
	tables?: string | null,
	/**
	 *  What the meta schema database held, absent where none was open.
	 * 
	 *  It decides `bin/property-type` outright, so a check taken against
	 *  another database was a claim about other types. The database's own bytes
	 *  rather than the stamp it carries, because the publisher restamps the
	 *  hash tables behind it on a schedule of its own - a database that has
	 *  gained two patches can still carry the stamp it was first published
	 *  under.
	 */
	schema?: string | null,
};

/**
 *  Whether a check can run, and what it is waiting on when it cannot.
 * 
 *  The precondition in [`hashtables_ready`](ModLibrary::hashtables_ready) as a
 *  control can be drawn from: a command a user may press now, one the app is
 *  already working towards, and one only they can clear. Per "The hashtables
 *  come first" in docs/ux/MOD_HEALTH.md.
 */
export type HealthCheckReadiness = 
/**  The tables are open, so a check runs. */
"ready" | 
/**  No tables yet, and a sync is on its way to fixing that. */
"syncing" | 
/**  No tables, and nothing fetching them but a sync the user starts. */
"unsynced";

/**
 *  Progress of a mod health sweep, emitted per mod.
 * 
 *  The mod is named by id rather than by title: the library view already holds
 *  every mod's name, and looking one up here would mean a `mod.config.json`
 *  read per mod on top of the check itself.
 */
export type HealthSweepProgress = {
	/**  Mods the sweep has finished, however they turned out. */
	completed: number,
	total: number,
	/**
	 *  The mods being read right now, by id. Several, because the sweep reads
	 *  more than one at a time.
	 */
	inFlight: string[],
};

/**  What one library sweep concluded. */
export type HealthSweepReport = HealthSweepReport_Serialize | HealthSweepReport_Deserialize;

/**  What one library sweep concluded. */
export type HealthSweepReport_Deserialize = {
	/**  What the sweep checked against. */
	basis: HealthCheckBasis_Deserialize,
	/**  Mods this run recorded a fresh verdict for. */
	checked: number,
	/**  Checkable mods this run did not take. */
	skipped: number,
	/**  Every mod in the library a repair would fix, by id. */
	repairable: string[],
	/**  Every mod in the library with findings and no fix for any, by id. */
	unrepairable: string[],
};

/**  What one library sweep concluded. */
export type HealthSweepReport_Serialize = {
	/**  What the sweep checked against. */
	basis: HealthCheckBasis_Serialize,
	/**  Mods this run recorded a fresh verdict for. */
	checked: number,
	/**  Checkable mods this run did not take. */
	skipped: number,
	/**  Every mod in the library a repair would fix, by id. */
	repairable: string[],
	/**  Every mod in the library with findings and no fix for any, by id. */
	unrepairable: string[],
};

/**
 *  What the library sweep has to say for itself this launch.
 * 
 *  The run starts with the app and can be over before a webview exists to hear
 *  it announced, so the outcome is kept for whoever asks next rather than only
 *  emitted — the same reason
 *  [`LayoutMigrationState`](crate::mods::LayoutMigrationState) is kept.
 */
export type HealthSweepState = HealthSweepState_Serialize | HealthSweepState_Deserialize;

/**
 *  What the library sweep has to say for itself this launch.
 * 
 *  The run starts with the app and can be over before a webview exists to hear
 *  it announced, so the outcome is kept for whoever asks next rather than only
 *  emitted — the same reason
 *  [`LayoutMigrationState`](crate::mods::LayoutMigrationState) is kept.
 */
export type HealthSweepState_Deserialize = 
/**  The startup pass has not reported yet, so the answer is still coming. */
({ status: "pending" }) & { completed?: never; report?: never; total?: never } | 
/**
 *  It ran and had nothing to re-check, which is every launch on the same
 *  game build under the same manager.
 */
({ status: "idle" }) & { completed?: never; report?: never; total?: never } | 
/**  It is working through the mods it owes a check. */
({ status: "running"; completed: number; total: number }) & { report?: never } | 
/**  It finished, and this is what the library looks like. */
({ status: "finished"; report: HealthSweepReport_Deserialize }) & { completed?: never; total?: never };

/**
 *  What the library sweep has to say for itself this launch.
 * 
 *  The run starts with the app and can be over before a webview exists to hear
 *  it announced, so the outcome is kept for whoever asks next rather than only
 *  emitted — the same reason
 *  [`LayoutMigrationState`](crate::mods::LayoutMigrationState) is kept.
 */
export type HealthSweepState_Serialize = 
/**  The startup pass has not reported yet, so the answer is still coming. */
({ status: "pending" }) & { completed?: never; report?: never; total?: never } | 
/**
 *  It ran and had nothing to re-check, which is every launch on the same
 *  game build under the same manager.
 */
({ status: "idle" }) & { completed?: never; report?: never; total?: never } | 
/**  It is working through the mods it owes a check. */
({ status: "running"; completed: number; total: number }) & { report?: never } | 
/**  It finished, and this is what the library looks like. */
({ status: "finished"; report: HealthSweepReport_Serialize }) & { completed?: never; total?: never };

/**  What one timed pass over the library cost. */
export type HealthTiming = {
	/**  Whether the pass repaired, or only checked. */
	repaired: boolean,
	/**  Wall-clock milliseconds for the whole pass, concurrency included. */
	totalMs: number,
	/**  One row per mod, slowest first. */
	mods: ModTiming[],
};

/**  A [`BinHash`] written as `0x` and eight hex digits, which is how a user reads one. */
export type HexBinHash = string;

/**
 *  A setting or an action the evidence points at, under the verdict.
 * 
 *  A code on the wire and in the store. The frontend catalog owns the sentence
 *  (ADR-0017), and the report text takes the sentences from there.
 */
export type Hint = "system-checks" | "update-manager" | "rebuild-overlay" | "check-game-path" | "texture-dimensions" | "repair-install" | "update-driver" | "free-memory" | "open-project" | "start-first" | "scan-up-front" | "copy-report" | "disable-suspect" | "remove-skinhack" | "reimport-mod" | "repair-game" | "elevate" | "signature" | 
/**
 *  A modded archive was in the game, and a texture far larger than what it
 *  replaces raises the odds of an allocation failing.
 */
"large-textures" | 
/**  An overlay file was held open, usually by a game still running. */
"close-game" | 
/**
 *  A shader failed with no programs named, which a shader definition
 *  outside the game's shaders bin reads as.
 */
"shader-definition";

/**  Which way a step through an edit history goes. */
export type HistoryStep = 
/**  Revert the latest edit. */
"undo" | 
/**  Apply the latest reverted edit again. */
"redo";

/**  The action a global hotkey triggers when pressed. */
export type HotkeyAction = "reloadMods" | "killLeague";

/**  One effect a skin wears for as long as the character stands. */
export type IdleEffect = {
	/**  `effectKey`, `0x` and eight hex digits. */
	effectKey: string,
	/**  The system the skin's resolver maps the key to, where this document declares it. */
	system: string | null,
	/**  `boneName`, the joint the effect rides. */
	bone: string,
	/**  `targetBoneName`, the joint it aims at, and empty for one that aims at none. */
	targetBone: string,
	/**  `Position`, the effect's offset from its joint. */
	position: [(number | null), (number | null), (number | null)],
};

/**  The `.modignore` line that keeps an entry out of a package. */
