	/**  The folder its paths name it by, such as `Ahri` or `TFT15_Ahri`. */
	id: string,
	/**  Its name in the string table, where the table holds one. */
	name: string | null,
	/**  The square icon of its base skin. */
	icon: UiTexture | null,
