/**
 *  What a frontend crash reports, as the boundary and the two window handlers
 *  hand it over.
 */
export type UiError = {
	/**  The error's constructor name, which is what an issue groups on. */
	name: string,
	message: string,
	/**  The stack as the engine wrote it, unresolved until the maps are uploaded. */
	stack: string | null,
	/**  Which components were mounted, where React gives one. */
	componentStack: string | null,
	/**  The route the reader was on, which is the location a crash carries. */
	route: string | null,
	/**  Whether anything caught it, which the vendor draws on an issue. */
	handled: boolean,
};

/**  One loadable a controller links. */
export type UiFile = {
	/**  The controller field that links it, such as `BaseLoadable` or `RTLOverride`. */
	slot: string,
	role: UiFileRole,
	/**  The chunk's path, or its sixteen hex digits where no table names it. */
	path: string,
	/**  Absent where nothing on this machine holds the chunk. */
	asset: AssetRef | null,
};

/**  What a loadable is to its controller. */
export type UiFileRole = 
/**  The scene bin the view draws: `BaseLoadable`, or the loadable the view was opened on. */
"base" | 
/**  Another `UiPropertyLoadable`, a base of its own that the view does not draw. */
"loadable" | 
/**  A `UiPropertyOverrideLoadable`, a `PTCH` over the base. */
"override";

/**
 *  A `GameFontDescription`, with its `FontType` and `FontResolutionData` followed.
 * 
 *  Every colour is `r, g, b, a`.
 */
export type UiFont = {
	/**  The description's object path, or its hash where no table names it. */
	path: string,
	/**  Its `name` field. */
	name: string,
	color: [number, number, number, number],
	outlineColor: [number, number, number, number],
	shadowColor: [number, number, number, number],
	glowColor: [number, number, number, number],
	/**  `fillTextureName`, the texture the fill samples. */
	fill: UiAsset | null,
	/**  The `FontType`'s faces, one per locale. */
	faces: UiFontFace[],
	/**  `FontResolutionData.autoScale`. */
	autoScale: boolean,
	/**  The `FontResolutionData`'s sizes, one list per locale. */
	sizes: UiFontSizes[],
};

/**  The fonts a text can link and the faces a font can draw with, as a picker lists them. */
export type UiFontCatalog = {
	/**  Every `GameFontDescription`, the project's first. */
	fonts: UiFontChoice[],
	/**  Every `FontType`, the project's first. */
	types: UiFontChoice[],
};

/**  One `GameFontDescription` or `FontType` of a [`UiFontCatalog`]. */
export type UiFontChoice = {
	/**  The object, as `0x` and eight hex digits. */
	entry: string,
	/**  The object path, or its hash where no table names it. */
	path: string,
	/**  A font's `name` field, and empty for a face. */
	name: string,
	/**  The file the first locale draws with regularly, a font's through its `typeData`. */
	face: string | null,
	/**  A font's `typeData`, the `FontType` it draws with, as `0x` and eight hex digits. */
	typeData: string | null,
	/**  How many locales the face lists, a font's through its `typeData`. */
	locales: number,
	/**  Whether the open document declares it, rather than the game's `ux/fonts`. */
	project: boolean,
};

/**  A `FontLocaleType`: the files a locale draws a font with. */
export type UiFontFace = {
	/**  `localeName`, such as `en_us`. */
	locale: string,
	regular: UiAsset,
	bold: UiAsset | null,
};

/**  A `FontResolution`, in pixels at `screenHeight`. */
export type UiFontResolution = {
	screenHeight: number,
	fontSize: number,
	outlineSize: number,
	/**  `shadowDepthX` and `shadowDepthY`. */
	shadowDepth: [number, number],
};

/**  A `FontLocaleResolutions`: the sizes a locale draws a font at. */
export type UiFontSizes = {
	locale: string,
	resolutions: UiFontResolution[],
};

/**  A managed layout's `LayoutStyle` and `Region`, which place its children per `0x1413E4740`. */
export type UiLayout = {
	/**  The `Region` the children lay out in, as `0x` and eight digits. */
	region: string | null,
	kind: UiLayoutKind,
	/**
	 *  `HorizontalJustification` and `VerticalJustification`: 0, 1 and 2 the start, centre and
	 *  end, 3 the free space shared around every child and 4 between them.
	 */
	justify: [number, number],
	/**  `HorizontalFillDirection` and `VerticalFillDirection`, 1 filling from the far edge. */
	fill: [number, number],
	/**  A grid's `FillPriority`, non-zero filling columns first. */
	fillPriority: number,
	/**
	 *  Where a child sits across its row or column, 0, 1 and 2 the start, centre and end: a
	 *  horizontal list's `RowVerticalAlignment`, a vertical list's `ColumnHorizontalAlignment`,
	 *  and a grid's `RowHorizontalAlignment` then `RowVerticalAlignment`.
	 */
	cross: [number, number],
	/**  `IgnoreDisabledElements`, which leaves a disabled child out of the layout. */
	ignoreDisabled: boolean,
};

/**  The class of a `LayoutStyle`. */
export type UiLayoutKind = "horizontalList" | "verticalList" | "grid";

/**  The textures and names a preview fills a controller's elements with. */
export type UiLoadout = {
	champion: string,
	/**  The champion's name in the string table, where its record names one. */
	nameKey: string | null,
	portrait: UiTexture | null,
	splash: UiTexture | null,
	/**  Q, W, E and R. */
	abilities: (UiTexture | null)[],
	passive: UiTexture | null,
	/**  D and F. */
	summoners: (UiTexture | null)[],
	keystone: UiTexture | null,
	substyle: UiTexture | null,
	/**  The six item slots, then the trinket. */
	items: (UiTexture | null)[],
};

/**  What an element draws. */
export type UiLook = 
/**  `UiElementIconData`. */
{ kind: "icon"; sprite: UiSprite | null; 
/**  `Color` as `r, g, b, a`. */
color: [number, number, number, number]; useAlpha: boolean; flip: [boolean, boolean]; perPixelUvs: [boolean, boolean]; fillType: number; 
/**  The `StaticMaterialDef` it draws with in place of the UI shader. */
material: string | null } | 
/**  A `UiElementEffect*Data`. */
{ kind: "effect"; effect: UiEffect; sprite: UiSprite | null; flip: [boolean, boolean]; perPixelUvsX: boolean } | 
/**  `UiElementTextData`. */
{ kind: "text"; 
/**  The index into [`UiView::fonts`]. */
font: number | null; 
/**  The index into [`UiView::style_sheets`]. */
styleSheet: number | null; traKey: string; 
/**  `TextAlignmentHorizontal` and `TextAlignmentVertical`. */
align: [number, number]; wrap: number; flipForRtl: boolean; iconScale: number | null; 
/**  The smallest scale a shrinking `wrap` draws at. */
minScale: number | null; 
/**  The element's own `Color`, over the font's. */
color: [number, number, number, number] | null } | 
/**  `UiElementParticleSystemData`. */
{ kind: "particle"; system: string | null; scale: number | null; atElementLayer: boolean } | 
/**  `UiElementRegionData`, an invisible rect. */
{ kind: "region" } | 
/**  `UiElementScissorRegionData`, the clip rect of the scene `scene`, as `0x` and eight digits. */
{ kind: "scissor"; scene: string | null } | 
/**  A `UiElementGroupData` or a class under it. */
{ kind: "group"; 
/**  The `Elements` list, as `0x` and eight digits each. */
children: string[]; 
/**  The button or slider states, each drawing only its own elements. */
states: UiButtonState[]; 
/**  The group's `Alpha`, and 1 for a class that carries none. */
alpha: number | null; 
/**
 *  How a `UiElementGroupManagedLayoutData` places its children, and none for any
 *  other group.
 */
layout: UiLayout | null; 
/**  What a `UiElementGroupButtonData` holds beyond its states, and none for any other group. */
button: UiButton | null; 
/**  What a `UiElementGroupMeterData` holds, and none for any other group. */
meter: UiMeter | null } | 
/**  `UiElementSpineAnimationData`, drawn as a placeholder. */
{ kind: "spine" } | 
/**  A class the read does not know. */
{ kind: "unknown" };

/**
 *  What a `UiElementGroupMeterData` holds, per "Meters" in docs/research/ui-data-layout.md. Each
 *  element is `0x` and eight digits.
 */
export type UiMeter = {
	/**  `BarElements`, the children the fill cuts. */
	bars: string[],
	/**  `FillDirection`. */
	direction: number,
	/**  `StartPercentage`, the fill the meter starts at, 0 to 1. */
	start: number | null,
	/**  `IsEnabled`, true by the class's default. */
	enabled: boolean,
	/**  The `TipStyle`, none where the file writes none or a class the read does not know. */
	tip: UiMeterTip | null,
};

/**  A meter's `TipStyle`, the children drawn at the fill's edge. */
export type UiMeterTip = {
	style: UiTipStyle,
	/**  `DirectionalTipElements`. */
	elements: string[],
	/**  A double-sided tip's `ReverseDirectionalTipElements`. */
	reverse: string[],
	/**  A double-sided tip's `Sliver`. */
	sliver: string | null,
	/**  A glow-centered tip's unnamed `0xcc4c6d1d`, 0.5 by default. */
	glow: number | null,
};

/**  Where an element sits, `Position`. */
export type UiPosition = 
/**  `UiPositionRect`. */
{ kind: "rect"; rect: UiRect } | 
/**  `UiPositionPolygon`, drawn as its rect until its tessellation is known. */
{ kind: "polygon"; rect: UiRect; vertices: ([(number | null), (number | null)])[] } | 
/**  `UiPositionFullScreen`, the whole parent rect. */
{ kind: "fullScreen" };

/**  `UiPositionRect` and its `UIRect`, in the element's source resolution. */
export type UiRect = {
	/**  The top-left corner in source pixels. */
	position: [(number | null), (number | null)],
	size: [(number | null), (number | null)],
	/**  `SourceResolutionWidth` and `Height`. */
	source: [number, number],
	anchor: UiAnchor,
	ignoreGlobalScale: boolean,
	ignoreSafeZone: boolean,
	disableResolutionDownscale: boolean,
	/**  `DisablePixelSnappingX` and `Y`. */
	disablePixelSnapping: [boolean, boolean],
	minSize: [(number | null), (number | null)],
	maxSize: [(number | null), (number | null)],
};

/**  A template group the controller clones into a managed layout, as its fields name it. */
export type UiRepeat = {
	/**  The template, as `0x` and eight digits. */
	template: string,
	/**  The group whose managed layout the copies fill. */
	layout: string,
	/**  How many copies the controller makes at most. */
	count: number,
};

/**  What a controller fills an element with at run time. */
export type UiRole = 
/**  A champion ability's icon, 0 to 3 for Q to R. */
{ kind: "ability"; slot: number } | { kind: "passive" } | 
/**  A summoner spell's icon, 0 for D and 1 for F. */
{ kind: "summoner"; slot: number } | 
/**  An item's icon, 0 to 6 with the trinket last. */
{ kind: "item"; slot: number } | 
/**  The champion's square portrait. */
{ kind: "portrait" } | 
/**  The champion's loading screen art. */
{ kind: "splash" } | { kind: "keystone" } | 
/**  The secondary rune path. */
{ kind: "substyle" } | 
/**  A buff's icon. */
{ kind: "buff" } | 
/**
 *  An element the controller shows only in a state a resting slot is not in: an out of mana
 *  or crowd control overlay, a disabled border, a cooldown effect, a buff timer, a message, a
 *  health bar's fading trail, an augment. The elements under it go with it.
 */
{ kind: "hidden" } | 
/**  The key that casts or uses a slot. */
{ kind: "hotkey"; key: string } | 
/**
 *  A text the controller leaves blank at rest: a cooldown, a charge or stack count, a respawn
 *  timer.
 */
{ kind: "idle" } | { kind: "level" } | { kind: "health" } | 
/**  The ability resource, such as mana. */
{ kind: "resource" } | 
/**  An ability's resource cost. */
{ kind: "cost" } | { kind: "kda" } | { kind: "creepScore" } | { kind: "visionScore" } | { kind: "gold" } | { kind: "playerName" };

/**  One `UISceneData`. */
export type UiScene = {
	/**  The scene object, as `0x` and eight digits. */
	key: string,
	/**  The object path, where a table names it. */
	path: string | null,
	/**  The scene's `name` field. */
	label: string,
	class: string,
	/**  The `ParentScene` link, as `0x` and eight digits. */
	parent: string | null,
	layer: number,
	/**  The file's `Enabled`, which the controller usually sets at run time instead. */
	enabled: boolean,
	inheritScissoring: boolean,
};

/**
 *  A shader pair the client draws a UI command with. The client pairs them in code, so a
 *  vertex stage can serve several pixel stages.
 */
export type UiShader = "blend" | "opaque" | "copy" | "cooldown" | "cooldownLine" | "ammo" | "ammoLine" | "circleMaskCooldown" | "cooldownRadial" | "cooldownRadialFill" | "arcFill" | "glow" | "glowConstant" | "animation" | "fillPercentage" | "desaturate" | "circleMaskDesaturate" | "line" | "lineGraph" | "rotatingIcon" | "glowingRotatingIcon" | "animatedRotatingIcon" | "gradient" | "font" | "fontOutline" | "fontIcon";

/**  A 3-slice or 9-slice sprite. */
export type UiSlice = {
	kind: UiSliceKind,
	/**
	 *  The column edges, normalized, four for a horizontal or nine slice and two otherwise.
	 *  Absent for a `LooseUiTextureData` slice, whose edges follow from `uv` and `edges`.
	 */
	us: (number | null)[] | null,
	/**  The row edges, as `us`. */
	vs: (number | null)[] | null,
	/**  Left, right, top and bottom edge sizes in the element's source pixels. */
	edges: [(number | null), (number | null), (number | null), (number | null)],
};

export type UiSliceKind = "horizontal" | "vertical" | "nine";

/**  One ability's tooltip, per "The string" in docs/research/ui-data-layout.md. */
export type UiSpellTooltip = {
	name: string,
	/**  The key that casts the spell, none for the passive. */
	hotkey: string | null,
	/**  The tooltip string, its values at the rank and level read for, with no bonus stats. */
	text: string,
	/**  The tooltip string while Shift is held, none for a spell with no extended tooltip. */
	extended: string | null,
	/**  How many ranks the spell has, the top rank its values can read at. */
	ranks: number,
	/**  The spell's icon, which the tooltip's icon shows. */
	icon: UiTexture | null,
};

/**  A region of a texture: an IMAA entry or an `AtlasData` rect. */
export type UiSprite = {
	/**  The index into [`UiView::textures`]. */
	texture: number,
	/**  `u0, v0, u1, v1`, normalized to the texture. */
	uv: [(number | null), (number | null), (number | null), (number | null)],
	/**  The source image path a `LooseUiTextureData` names, where a table names it. */
	name: string | null,
	slice: UiSlice | null,
};

/**  A `CSSSheet`: the style tags and inline icons a text's markup names. */
export type UiStyleSheet = {
	path: string,
	styles: UiTextStyle[],
	icons: UiTextIcon[],
};

/**  A `CSSIcon`, drawn inline where the markup writes `%i:name%`. */
export type UiTextIcon = {
	name: string,
	texture: UiAsset | null,
	/**  The rect of `texture` the icon is, as `u0, v0, u1, v1`, and all of it where none. */
	uv: [(number | null), (number | null), (number | null), (number | null)] | null,
	/**  `YAdjustment`, in pixels. */
	yAdjustment: number | null,
};

/**  A `CSSStyle`, where each field it leaves unset keeps the run's own. */
export type UiTextStyle = {
	/**  The tag name, such as `spellActive`. */
	name: string,
	color: [number, number, number, number] | null,
	bold: boolean | null,
	italics: boolean | null,
	underline: boolean | null,
};

/**  A texture a sprite samples: an auto-atlas page or a hand-made sheet. */
export type UiTexture = {
	/**  The texture's path, or its sixteen hex digits where no table names it. */
	path: string,
	/**  Absent where nothing on this machine holds it. */
	asset: AssetRef | null,
	/**  An auto-atlas page rather than a sheet. */
	page: boolean,
};

/**  The class of a meter's `TipStyle`. */
export type UiTipStyle = "barExtension" | "doubleSided" | "glowCenteredOverlay";

/**
 *  One `TooltipViewData`: the parts a tooltip is laid out from, each as `0x` and eight digits,
 *  per "Tooltips" in docs/research/ui-data-layout.md.
 */
export type UiTooltip = {
	icon: string | null,
	iconOverlay: string | null,
	titleLeft: string | null,
	titleRight: string | null,
	subtitleLeft: string | null,
	subtitleRight: string | null,
	mainText: string | null,
	postScriptTitle: string | null,
	postScriptLeft: string | null,
	postScriptRight: string | null,
	backdrop: string | null,
	hrTop: string | null,
	hrBottom: string | null,
	/**  The line under an optional header sub-scene. */
	hrTopSubScene: string | null,
	/**  The line over an optional footer sub-scene. */
	hrBottomSubScene: string | null,
	caret: string | null,
	/**  The controller's `DefaultAdjustments`. */
	adjustments: UiTooltipAdjustments,
};

/**  One `PerLocaleTooltipAdjustments`: pixel nudges to the tooltip's stack. */
export type UiTooltipAdjustments = {
	/**  The unnamed `0x8b64dacd`: no `top_hr_y_pre` above the top line while the icon shows. */
	iconSkipsTopHrPre: boolean,
	titleY: number,
	topHrYPre: number,
	topHrYPost: number,
	bottomHrYPre: number,
	bottomHrYPost: number,
	bottomYPadding: number,
};

/**  A variant laid over the base scene bin, and what laying it did. */
export type UiVariant = {
	/**  The controller field that links it, such as `RTLOverride`. */
	slot: string,
	/**  Every patch record of the variant, in file order. */
	records: UiVariantRecord[],
	/**  The objects the variant adds, as `0x` and eight digits. */
	added: string[],
	/**  The base objects the variant deletes, as `0x` and eight digits. */
	deleted: string[],
};

/**  One patch record of a variant. */
export type UiVariantRecord = {
	/**  The object it patches, as `0x` and eight digits. */
	object: string,
	/**  The property path as the file writes it, such as `Position.UIRect`. */
	path: string,
	/**  The same path in wire segments, each field as eight hex digits. */
	fields: string,
	/**  Why the record did not apply, absent where it did. */
	skipped: string | null,
};

/**
 *  A view controller or a `UiPropertyLoadable`, and everything its base scene bin holds, resolved
 *  for drawing.
 */
export type UiView = {
	/**  The object the view was opened on, as `0x` and eight digits. */
	entry: string,
	/**  Its object path, where a table names it. */
	name: string | null,
	/**  Its class, or its hash where no table names it. */
	class: string,
	/**
	 *  The path `PathHashToSelf` hashes, which is the manifest and the page folder, where a
	 *  table names it.
	 */
	folder: string | null,
	/**  Every loadable the controller links, the base first. */
	files: UiFile[],
	/**  The variant drawn over the base, absent where the view draws the base alone. */
	variant: UiVariant | null,
	/**  The scenes of the base file, in file order. */
	scenes: UiScene[],
	/**  The elements of the base file, in file order. */
	elements: UiElement[],
	/**  The combo boxes of the base file, in file order. */
	comboBoxes: UiComboBox[],
	/**  The tooltip the controller lays out, where it is a `TooltipViewController`. */
	tooltip: UiTooltip | null,
	/**  Every texture a sprite names, which a sprite indexes. */
	textures: UiTexture[],
	/**  Every font a text names, which a text indexes. */
	fonts: UiFont[],
	/**  Every style sheet a text names, which a text indexes. */
	styleSheets: UiStyleSheet[],
	/**  The templates the controller clones into its layouts at run time. */
	repeats: UiRepeat[],
	/**  The elements the controller fills at run time, each with what it fills them with. */
	bindings: UiBinding[],
	/**  Every reference the read could not follow. */
	warnings: UiViewWarning[],
};

/**  A reference a view read could not follow. The view draws without it. */
export type UiViewWarning = 
/**  The controller links no `BaseLoadable` or `Loadable`. */
{ kind: "noBase" } | 
/**
 *  The base loadable is declared in another bin, which the object index finds once it is
 *  built.
 */
{ kind: "baseElsewhere"; entry: string } | 
/**  A loadable's chunk is on no layer and in no archive. */
{ kind: "missingFile"; path: string } | 
/**  A file is there and does not parse as a bin or a manifest. */
{ kind: "unreadableFile"; path: string; reason: string } | 
/**  A `LooseUiTextureData` names a key no loaded manifest holds. */
{ kind: "missingSprite"; element: string; name: string } | 
/**  A text links a `GameFontDescription` or a `CSSSheet` that `ux/fonts` does not hold. */
{ kind: "missingFont"; element: string; link: string } | 
/**  The variant asked for is in no override slot of the controller. */
{ kind: "unknownVariant"; slot: string } | 
/**  A variant's file is no `PTCH`, or the base it lays over is no `PROP`. */
{ kind: "notAPatch"; path: string };

/**  One uniform block, as the blob's `RDEF` laid it out. */
export type UniformBlock = {
	/**  The `RDEF` name: `$Globals`, `PerFrameVertexCB`. */
	name: string,
	/**  The block name in the GLSL, which carries the stage suffix. */
	glslName: string,
	/**  The buffer's size in bytes, a multiple of 16. */
	size: number,
	members: BlockMember[],
};

/**  Validation result for a project. */
export type ValidationResult = {
	valid: boolean,
	errors: string[],
	warnings: string[],
};

/**  One staged edit, addressed relative to its enclosing property. */
export type ValueEdit = 
/**  Add a missing schema field at its published default. */
{ type: "ensureProperty"; path: string; field: string } | 
/**  Give a null pointer its class. A non-null pointer retains its fields. */
{ type: "ensurePointer"; path: string; class: string } | 
/**
 *  Swap a pointer's class, keeping the fields both classes declare with one type. A
 *  null class clears the pointer.
 */
{ type: "replacePointer"; path: string; class: string | null } | 
/**  Insert an item into a list, map or option. */
{ type: "insertItem"; path: string; item: NewItem } | 
/**
 *  Insert a copy of the item at `from` into the list at `path`, at `index` or the end.
 *  `unique` names a string field whose text the copy makes unique among the object's
 *  list items.
 */
{ type: "copyItem"; from: string; path: string; index: number | null; unique: string | null } | 
/**
 *  Insert the value clipboard `text` carries into the list at `path`, at `index` or the
 *  end, with `unique` as for [`ValueEdit::CopyItem`].
 */
{ type: "pasteItem"; path: string; index: number | null; text: string; unique: string | null } | 
/**  Remove an item from a list, map or option. */
{ type: "removeItem"; path: string } | 
/**
 *  Set an existing leaf, including one created by an earlier staged edit. An empty
 *  option takes an item first, so the edit writes an optional field whatever it holds.
 */
{ type: "setLeaf"; path: string; value: LeafValue };

/**  What the manager concluded from one game. */
export type Verdict = Verdict_Serialize | Verdict_Deserialize;

/**  Which failure the classifier named. */
export type VerdictKind = 
/**  The DLL never attached, which is the common startup failure. */
"patcher-did-not-run" | 
/**  The overlay could not be built, so there was nothing to inject. */
"overlay-build-failed" | 
/**  The injection host never came up. */
"injection-host-failed" | "patcher-out-of-date" | "archive-rejected" | 
/**
 *  The scan rejected an archive for a Riot skin ported onto a base
 *  champion, which is the rejection a player has a word for.
 */
"skinhack-detected" | "overlay-disabled" | "unmodded" | "missing-data" | "corrupt-archive" | "texture-failed" | "out-of-memory" | "graphics-fault" | "stuck-loading" | "archive-skipped" | "ended-without-reason" | 
/**  The game ran from another install than the overlay was built for. */
"wrong-install" | 
/**  A shader did not compile, or a material had no pipeline to draw with. */
"shader-failed";

/**  What the manager concluded from one game. */
export type Verdict_Deserialize = StoredVerdict_Deserialize;

/**  What the manager concluded from one game. */
export type Verdict_Serialize = {
	kind: VerdictKind,
	/**
	 *  The title as it reads, from [`VerdictKind::title`] unless this verdict
	 *  named its own.
	 * 
	 *  Derived on the way in, so a stored incident cannot keep a title this
	 *  build has stopped using. Renaming a kind renames its history with it.
	 */
	title: string,
	/**
	 *  A title for something the kind's own does not cover, and `None` for
	 *  every verdict the predefined set already describes.
	 */
	titleOverride: string | null,
	/**  One or two sentences under the title. */
	cause: string,
	/**  The archive, the path's file name, or the step, where there is one. */
	subject: string | null,
	/**
	 *  What the game lost, which [`VerdictKind`] alone decides.
	 * 
	 *  Written out for a reader, and never read back. [`Self::kind`] decides it,
	 *  so reading it from a file would only let a stale one disagree.
	 */
	consequence: Consequence,
	/**  At most two. */
	hints: Hint[],
};

/**  One property of a resolved struct. */
export type VfxField = {
	/**  `0x` and eight hex digits. */
	hash: string,
	/**  The property as the tables name it. Absent where no table does. */
	name: string | null,
	/**  What the property holds, resolved. */
	value: VfxValue,
};

/**  One entry of a resolved map. */
export type VfxMapEntry = {
	/**
	 *  A named hash key by its name, an unnamed one as hex, and every other kind as the
	 *  wire form writes it.
	 */
	key: string,
	/**  What the entry holds, resolved. */
	value: VfxValue,
};

/**  The object a resolved struct holds the properties of, where a walk reached one. */
export type VfxObject = {
	/**  The object's path hash, `0x` and eight hex digits. */
	entry: string,
	/**  The object's path. Absent where no table names it. */
	name: string | null,
};

/**  One particle system, as the renderer reads it. */
export type VfxSystem = {
	/**  The object's path hash, `0x` and eight hex digits. */
	entry: string,
	/**  The object's path. Absent where no table names it. */
	name: string | null,
	/**  `0x` and eight hex digits. */
	classHash: string,
	/**  The class as the tables name it. Absent where no table does. */
	class: string | null,
	/**  The object's own properties, resolved. Always a [`VfxValue::Struct`]. */
	root: VfxValue,
	/**  Static previews of custom materials referenced by this system and its children. */
	materials: MaterialPreview[],
};

/**  One template of the catalog. */
export type VfxTemplate = {
	/**  The catalog's key, which the frontend's messages are named by. */
	id: string,
	kind: VfxTemplateKind,
	/**  The English name an emitter or a system made from it is written with. */
	name: string,
	/**  The rig a system template was tuned on, and `None` for an emitter template. */
	rig: TemplateRig | null,
	/**  The game patch the template was last checked on in game, and `None` for one not yet. */
	checked: string | null,
	/**  The emitters the template lands, in list order: itself for an emitter template. */
	emitters: TemplateEmitter[],
};

/**  Whether a template is one emitter or a whole system. */
export type VfxTemplateKind = "emitter" | "system";

/**  A value of a resolved system's tree. */
export type VfxValue = 
/**  A `Bool` or a `BitBool`. */
{ type: "bool"; value: boolean } | 
/**
 *  Every integer kind and every float, as one number, because the consumer does
 *  arithmetic on them.
 */
{ type: "number"; value: number | null } | 
/**  Two, three or four components. A `Color` is four channels as fractions. */
{ type: "vector"; values: (number | null)[] } | 
/**  Sixteen cells, row-major. */
{ type: "matrix"; values: (number | null)[] } | 
/**  A `String`, held as the file spells it. */
{ type: "string"; value: string } | 
/**  `0x` and eight hex digits, and the string behind it where a table names one. */
{ type: "hash"; hash: string; name: string | null } | 
/**
 *  A name field resolved to where its bytes live.
 * 
 *  `path` keeps the spelling the bin holds. `asset` is absent for a path nothing on
 *  this machine holds, which is not an error.
 */
{ type: "asset"; path: string; asset: AssetRef | null } | 
/**  A `Link` whose target is not an object of this document. */
{ type: "link"; hash: string; name: string | null } | 
/**  A `Struct` with a class, an `Embedded`, or the object a `Link` reached. */
{ type: "struct"; classHash: string; class: string | null; fields: VfxField[]; 
/**  The object whose properties these are, absent for an embedded struct. */
object: VfxObject | null } | 
/**  A `Container` or an `UnorderedContainer`. */
{ type: "container"; items: VfxValue[] } | 
/**  A `Map`, its entries in the order the file holds them. */
{ type: "map"; entries: VfxMapEntry[] } | 
/**  A `Struct` with a class hash of zero. */
{ type: "null" } | 
/**  A `None` leaf, or an optional holding nothing. */
{ type: "none" } | 
/**  A leaf this build has no reading for. */
{ type: "undrawn" };

/**  A variant a view draws over its base: the override slot, and its open document where one is. */
export type ViewVariant = {
	slot: string,
	document: BinDocumentId | null,
};

/**
 *  A single entry in the WAD blocklist.
 * 
 *  `Exact` matches a literal filename (case-insensitively). `Regex` matches
 *  against every WAD filename in the game install; the pattern is always
 *  applied case-insensitively.
 */
export type WadBlocklistEntry = { kind: "exact"; value: string } | { kind: "regex"; value: string };

/**
 *  Payload for the `patcher-wad-scan-failed` event, emitted when the injected
 *  DLL's integrity scan rejects one or more modded archives. When this fires
 *  the patcher auto-stops and applies no mods for the session.
 */
export type WadScanFailedPayload = {
	/**
	 *  The archives that failed the scan, de-duplicated. May be empty if no
	 *  names could be parsed from the scan log.
	 */
	failures: WadScanFailureInfo[],
};

/**  One archive that failed the integrity scan, sent in [`WadScanFailedPayload`]. */
export type WadScanFailureInfo = {
	/**  The offending archive (e.g. `TahmKench.wad.client`), if its name parsed. */
	wad: string | null,
	/**
	 *  The code the scan reported, an NTSTATUS-style one the game raised
	 *  (`c0000229`), or a word the DLL's own checks named (`mod_wad`).
	 */
	status: string,
	/**
	 *  What [`ScanStatus::parse`] makes of `status`, so the dialog reads a
	 *  rejection the way the Games tab does instead of keeping a second table.
	 */
	reading: ScanStatus,
};

/**  Which set of an install's archives a reader browses. */
export type WadSource = 
/**  The game's `*.wad.client` archives under `Game/DATA/FINAL`. */
"game" | 
/**  The League client's `*.wad` archives under `Plugins`. */
"lcu";

/**  An image the webview draws from the file's own bytes. */
export type WebImage = "svg" | "gif" | "webp" | "bmp" | "ico";

/**  The winding a pass culls, `windingToCull` on the wire. */
export type Winding = 
/**  Clockwise, `0`, which 436 shipped passes cull for an inverted hull. */
"cw" | 
/**  Counter-clockwise, `1`, the class default. */
"ccw";

export type WorkshopAuthor = {
	name: string,
	role: string | null,
};

/**
 *  Domain errors specific to workshop operations.
 * 
 *  Sent over IPC as the `context` payload of an `AppError` with code `WORKSHOP`.
 *  Frontend code can switch on `kind` to handle each variant.
 */
export type WorkshopError = 
/**  One or more files already exist in the target layer directory. */
{ kind: "LAYER_FILE_CONFLICT"; conflicts: string[] } | 
/**  A `.modignore` line the matcher cannot compile, which held its save back. */
{ kind: "IGNORE_RULE_PATTERN"; line: number; message: string } | 
/**
 *  A `.modignore` line the matcher cannot compile, which failed a pack.
 * 
 *  Names its file, because a pack reads the nested files as well as the
 *  root one and only the line and the file together place the pattern.
 */
{ kind: "PACK_IGNORE_PATTERN"; path: string; line: number; message: string } | 
/**  A root text file that changed on disk under the buffer being saved. */
{ kind: "TEXT_FILE_CHANGED"; path: string } | 
/**  A layer's declarations manifest that changed on disk since it was read. */
{ kind: "DECLARATIONS_CHANGED_ON_DISK"; path: string } | 
/**
 *  A layer whose declarations manifest is JSON or TOML. The editor writes
 *  `game_data.yaml` only.
 */
{ kind: "DECLARATIONS_NOT_YAML"; path: string } | 
/**  A layer's declarations manifest that does not load. */
{ kind: "DECLARATIONS_INVALID"; path: string; message: string } | 
/**  An edit the text of a declarations manifest cannot take. */
{ kind: "DECLARATIONS_UNEDITABLE"; path: string; reason: string };

/**
 *  Mirror of [`ltk_file::LeagueFileKind`] with `ts-rs` bindings. Kept in sync
 *  manually — the upstream enum is small and stable, and mirroring lets us
 *  export a TypeScript union without fighting external crate attributes.
 */
export type WorkshopFileKind = "animation" | 
/**  A layer's game data declarations manifest, which [`LeagueFileKind`] has no kind for. */
"game_data" | "jpeg" | "light_grid" | "lua_obj" | "map_geometry" | "png" | "tga" | "preload" | "property_bin" | "property_bin_override" | "riot_string_table" | "simple_skin" | "skeleton" | "static_mesh_ascii" | "static_mesh_binary" | "svg" | "texture" | "texture_dds" | "unknown" | "world_geometry" | "wwise_bank" | "wwise_package";

export type WorkshopLayer = {
	name: string,
	displayName: string,
	priority: number,
	description: string | null,
	stringOverrides: { [key in string]: { [key in string]: string } },
};

/**  Runtime info about a layer's content directory, fetched separately from config. */
export type WorkshopLayerInfo = {
	wadFiles: string[],
};

/**  A workshop project displayed in the UI. */
export type WorkshopProject = {
	/**  Stable id the route names the project by, derived from its path */
	id: string,
	/**  Absolute path to the project directory */
	path: string,
	/**  Project slug name (directory name) */
	name: string,
	/**  Human-readable display name */
	displayName: string,
	/**  Semantic version string */
	version: string,
	/**  Project description */
	description: string,
	/**  List of authors */
	authors: WorkshopAuthor[],
	/**  Categorization tags */
	tags: string[],
	/**  Champion names this mod applies to */
	champions: string[],
	/**  Map identifiers this mod applies to */
	maps: string[],
	/**  Project layers */
	layers: WorkshopLayer[],
	/**  Path to thumbnail image if exists */
	thumbnailPath: string | null,
	/**  Last modification time */
	lastModified: string,
	/**  Whether the project sits in the workshop folder or was opened from elsewhere */
	location: ProjectLocation,
	/**  When the project was last opened in the editor */
	lastOpened: string | null,
};

/**  A sampler's address mode, `addressU` and `addressV` on the wire. */
export type Wrap = "repeat" | "clamp" | "mirror" | "border";

